"""Writes paper/fix_null.tex and paper/fix_lcp2.tex from fix/*.json (FIX_PREREG.md outcomes)."""
import os, json
V2 = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); FD = os.path.join(V2, "results", "fix")
F = json.load(open(os.path.join(FD, "fix_results.json"))); Cv = json.load(open(os.path.join(FD, "null_caveat.json")))
N, S, Dc = F["null"], F["sim"], F["LCP2_decision"]
n0 = lambda x: f"{x:,.0f}".replace(",", "{,}"); f3 = lambda x: f"{x:.3f}"; f2 = lambda x: f"{x:.2f}"
s1, s2 = N["S1"], N["S2"]
null = rf"""\paragraph{{A real-cell null with exact truth (plan frozen before the run).}} To test the leak on real cells with known truth, we pooled the nuclei of each supertype and randomly reassigned them to pseudo-donors with the real donors' cell numbers ({s1['K']} reassignments per supertype; \texttt{{prereg/FIX\_PREREG.md}}). The pseudo-donors are exchangeable draws from one population, so the between-donor covariance is exactly zero for every pair while every real within-cell program is kept; every call is a false discovery. In Micro-PVM\_1 (79 pseudo-donors, median 15 nuclei) pseudobulk made {n0(s1['PB']['mean_calls'])} false discoveries per reassignment (range {n0(min(s1['PB']['calls']))}--{n0(max(s1['PB']['calls']))}) and in Micro-PVM\_3 {n0(s2['PB']['mean_calls'])} ({n0(min(s2['PB']['calls']))}--{n0(max(s2['PB']['calls']))}); LCP made no calls in any reassignment of either supertype (mean {n0(s1['LCP']['mean_calls'])} and {n0(s2['LCP']['mean_calls'])}). Pseudobulk's per-pair type-I error at $\alpha=0.05$ was {f2(s1['PB']['typeI'])} and {f2(s2['PB']['typeI'])}, and {f2(s1['PB']['typeI_top1'])} and {f2(s2['PB']['typeI_top1'])} for the 1\% most within-correlated pairs. LCP's per-pair type-I error was {f3(s1['LCP']['typeI'])} and {f3(s2['LCP']['typeI'])} ({f3(s1['LCP']['typeI_top1'])} and {f3(s2['LCP']['typeI_top1'])} for the top 1\%), so by the frozen criterion LCP does not fully hold this null at the single-pair level, although none of that excess reaches the multiple-testing threshold. One caveat: pooling turns the real donors' between-donor covariance into within-pseudo-donor covariance, so this null's within-donor structure is somewhat stronger than real donors' (median absolute within-donor correlation {f3(Cv['S1']['med_absrw_null'])} versus {f3(Cv['S1']['med_absrw_realdonor'])} in Micro-PVM\_1), and {f2(Cv['S1']['frac_nullPBcalls_that_are_real_LCP_calls'])} of pseudobulk's false calls are pairs that LCP calls between real donors (base rate {f2(Cv['S1']['real_LCP_call_rate'])}).
"""
L = {d: S[d] for d in S}
lcp2 = rf"""\paragraph{{LCP2: correcting for the variance of the leak estimate (plan frozen before the run).}} Theorem~\ref{{thm:lcp}}(b) identifies a null variance term of order $1/n_d$ that LCP's scaling omits: the variance of the per-donor leak estimate and its covariance with $r_{{dj}}r_{{dk}}$. LCP2 estimates it per donor by a delete-one-nucleus jackknife, $\hat\delta_d=\widehat{{\mathrm{{Var}}}}(r_{{dj}}r_{{dk}}-\tilde\ell_d)-\widehat{{\mathrm{{Var}}}}(r_{{dj}}r_{{dk}})$, and adds $\max(\sum_d\hat\delta_d,0)$ to the denominator of the scaling factor; the permutation reference is unchanged. On new seeds and the held-out gene panel ($R=100$ per design), LCP2's FDR was {f3(L['F_D16']['LCP2']['FDR'])}\,({f3(L['F_D16']['LCP2']['FDR_mcse'])}) at 16 donors with ${{\sim}}40$ cells (LCP {f3(L['F_D16']['LCP']['FDR'])}) and {f3(L['F_S1']['LCP2']['FDR'])}\,({f3(L['F_S1']['LCP2']['FDR_mcse'])}) with the Micro-PVM\_1 cell numbers (LCP {f3(L['F_S1']['LCP']['FDR'])}), and stayed below 0.05 in the other four designs ({f3(min(L[d]['LCP2']['FDR'] for d in ('F_D24','F_D40','F_S2','F_D16_n100')))}--{f3(max(L[d]['LCP2']['FDR'] for d in ('F_D24','F_D40','F_S2','F_D16_n100')))}). In the real-cell null its per-pair type-I error was {f3(s1['LCP2']['typeI'])} and {f3(s2['LCP2']['typeI'])}. The price is power: {f3(L['F_D24']['LCP2']['power'])} versus {f3(L['F_D24']['LCP']['power'])} at 24 donors ({f2(L['F_D24']['LCP2']['power']/L['F_D24']['LCP']['power'])} of LCP's), {f3(L['F_D40']['LCP2']['power'])} versus {f3(L['F_D40']['LCP']['power'])} at 40, and {f3(L['F_S1']['LCP2']['power'])} versus {f3(L['F_S1']['LCP']['power'])} with Micro-PVM\_1 cell numbers. Our frozen rule required at least 0.9 of LCP's power at 24 and 40 donors, so LCP2 {'replaces' if Dc['adopt'] else 'does not replace'} LCP; as a post hoc recommendation, we suggest LCP2 for designs like the two where LCP failed (16 donors with ${{\sim}}40$ cells; ${{\sim}}15$ cells per donor), accepting its lower power.
"""
open(os.path.join(V2, "paper", "fix_null.tex"), "w").write(null); open(os.path.join(V2, "paper", "fix_lcp2.tex"), "w").write(lcp2)
print(null); print(lcp2)
